<?php require_once __DIR__.'/../includes/functions.php';require_role('admin');$rows=$pdo->query('SELECT a.title,a.due_date,s.name subject_name,t.first_name teacher_first FROM assignments a JOIN subjects s ON s.id=a.subject_id JOIN teachers t ON t.id=a.teacher_id ORDER BY a.due_date DESC')->fetchAll();$pageTitle='Assignments';$base='../';require __DIR__.'/../includes/header.php';?><div class='layout'><?php require __DIR__.'/../includes/sidebar.php';?><section class='content'><div class='card'><h1>Assignments</h1><div class='table-wrap'><table class='table'><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>